    g.add(back, left, right, roof, pillarL, pillarR, lintel);
    const cap = new THREE.Mesh(new THREE.SphereGeometry(1.18, 12, 5, 0, Math.PI * 2, 0, Math.PI * 0.32), snowCapMat);
