const ROCKET_PAD = { x: 2, z: -9.5 };
const ROCKET_PAD_R = 2.05;           // 바지선 갑판 반경 (2.4× 로켓 체급) — 스윕·항로 회피 버퍼와 공유
const ROCKET_PAD_DECK_Y = -0.18;     // 갑판 상판 — 최대 수면 -0.34(OCEAN_LEVEL -0.52 + 조수 0.055 + 파도 0.123) 위 0.16
