        ctx.fillStyle = 'rgba(160,150,130,0.5)';
        ctx.beginPath();
        ctx.ellipse(Math.random() * s, Math.random() * s, 3 + Math.random() * 3, 2 + Math.random() * 2, Math.random() * 3, 0, Math.PI * 2);
