document.body.appendChild(chatBar);
chatInput.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.isComposing) sendWorldChat(); e.stopPropagation(); });
// 📱 iOS: 화면 키보드가 닫힐 때 페이지가 밀려 올라간 채로 남는 일이 있어 원점으로 되돌린다.
