    carTp: (x, z, h) => { CAR.x = x; CAR.z = z; if (Number.isFinite(h)) CAR.heading = h; CAR.vel = 0; carCollider.x = x; carCollider.z = z; carGroup.position.set(x, world.groundHeightAt(x, z), z); carGroup.rotation.set(0, CAR.heading, 0); },
