        if (islandOf(x, z) >= 0 || onBridge(x, z) || Math.hypot(x, z) > EXPLORE_R) return false;
        if (Math.hypot(x - FERRY.x, z - FERRY.z) < 1.6 || window.__nearFerryPier(x, z, 1.1)) return false;
        if (Math.hypot(x - PLANE.x, z - PLANE.z) < 1.6) return false;
