        if (Math.hypot(x - FERRY.x, z - FERRY.z) < 1.8 || window.__nearFerryPier(x, z, 1.3)) return false;
        if (Math.hypot(x - BOAT.x, z - BOAT.z) < 1.5) return false;
        if (islandOf(x, z) < 0 && !onBridge(x, z)) return true;   // 물 위는 자유
