            for (let i = 0; i < 4; i++) { const a = i * 1.75; const dot = new THREE.SphereGeometry(0.0014, 5, 4); dot.translate(Math.cos(a) * lr * 0.46, ly + 0.0035 + lr * fh * 0.82, Math.sin(a) * lr * 0.46); add(dot, 0x9a6a3c, 0x774f28, { curve: 1 }); }
