            for (let i = 0; i < 3; i++) { const a = i * 2.2; const dot = new THREE.SphereGeometry(0.0014, 5, 4); dot.translate(Math.cos(a) * lr * 0.4, ly + 0.006 + lr * 0.3, Math.sin(a) * lr * 0.4); add(dot, 0x7a4a28, 0x5c3418, { curve: 1 }); }
