    if (p.poiWalk || (rocketRide && !rocketRide.empty && (rocketRide.p === p || rocketRide.friend === p))) { showToast('🛰️ 우주에선 전화가 안 터져요 — 지상에서 불러요'); return; }
    const friend = pets.find((q) => q !== p);
