            bub.scale.setScalar(0.035 + Math.random() * 0.045);
            bub.position.set(m.position.x + (Math.random() - 0.5) * 0.2, waveYAt(m.position.x, m.position.z) + 0.03, m.position.z + (Math.random() - 0.5) * 0.2);
            scene.add(bub);
