const seabedDug = (k) => !!dugSeabed[k] && Date.now() - dugSeabed[k] < 72 * 3600 * 1000;
const WRECK_AT = { x: 31.5, z: -18.5 };   // 난파선 — 먼바다 고정 POI (심연 방향)
// 🗺️ 해저 포그오브워: 잠수 중 청크가 로드되면 그 보물 자리를 '알게 된다' (소나식) — 지도에 ✕로 남는다
