            for (let a = 0; a <= 22; a++) {
                const t = (a / 22) * Math.PI * 2;
                const rr = r + Math.sin(t * lobes + ph) * wob;
                const x = ccx + ox + Math.cos(t) * rr, y = ccy + oy + Math.sin(t) * rr;
                if (a === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();
