    const waterAt = (x, z) => {
        if (Math.hypot(x - pondPropRef.x, z - pondPropRef.z) < 0.55) return 'pond';
        if (islandOf(x, z) < 0 && Math.hypot(x, z) < EXPLORE_R) return 'sea';
        return null;
    };
