refreshFruit();   // 🍎 과일 초기 매달기 — 레이아웃·소품이 다 선 뒤 1회
applyHouseLight();   // 💡 전등 초기 상태 (수동 저장 > 밤 자동)
loadGroundFruits();   // 낙과 복원 (시들 시간 지난 건 조용히 흙으로)
// ---- 🔄 버전 워치독: 폰 PWA/홈화면 웹뷰는 오래 살아서 새 배포를 모른다 — 화면에 복귀할 때
// world.js의 ETag를 HEAD로 재확인해 바뀌었으면 토스트 후 자동 새로고침. 데스크톱/테스트 서버처럼
// ETag가 없으면 조용히 무력화된다 (LAN HEAD 1회 = 무비용). ----
let buildTag = null;
async function fetchBuildTag() {
    try {
        const r = await fetch('js/world.js', { method: 'HEAD', cache: 'no-store' });
        return r.headers.get('etag') || r.headers.get('last-modified') || null;
    } catch (e) { return null; }
}
fetchBuildTag().then((t) => { buildTag = t; });
document.addEventListener('visibilitychange', async () => {
    if (document.visibilityState !== 'visible' || !buildTag) return;
    const t = await fetchBuildTag();
    if (t && t !== buildTag) {
        buildTag = t;   // 재진입 중복 방지
        showToast('🔄 새 버전이 도착했어요 — 새로고침합니다');
        setTimeout(() => location.reload(), 1400);
    }
});
// ==== 🐟 카툰 어종 조형 — 지오는 실루엣만, 색·무늬는 아틀라스 텍스처 ==========================
// 규약 5개. 종을 추가할 때 이 5개를 채우면 끝난다.
//   ① 프로파일 표는 **체장 1 기준 정규화** — top/bot/hw 전부 체장 비율. hw 열이 곧 단면 종횡비 조절기다
//      (메기 머리는 hw > 체고 → 납작 넓음, 꼬리는 hw ≪ 체고 → 장어형. 별도 aspect 함수 불필요)
//   ② 아틀라스 1024×1024 = 256² 셀 16개. u→둘레(이음선=배 용골) · v→체장(**머리 우선 워프** 필수)
//   ③ 무늬는 만화식 — 굵고 성긴 초승달 비늘 + 일정 굵기 외곽선. 촘촘하면 96px에서 노이즈가 되고 원경에 모아레
//   ④ 지느러미 텍스처는 **회색조 공용 1셀**, 색은 정점색으로 종별 착색(vertexColors × map) → 셀 13개 절약
//   ⑤ 정점색은 형태 음영 + 지느러미 착색만. 색·무늬는 텍스처 몫
const FA_W = 2048, FA_H = 1024, FA_CELL = 256, FA_COLS = 8, FA_ROWS = 4;
const FA_KU = 1 / FA_COLS, FA_KV = 1 / FA_ROWS;   // ⚠️ 비정사각 아틀라스 — u·v 스케일이 다르다(하나로 쓰면 세로가 늘어난다)
const faRect = (i) => {
    const c = i % FA_COLS, r = (i / FA_COLS) | 0;
    return { x: c * FA_CELL, y: r * FA_CELL, u0: c * FA_KU, v1: 1 - r * FA_KV };
};
const FA_FIN = 13;   // 공용 지느러미 셀 · 15 = 흰색+개구리눈+장화속 · 16~19 = 조개 · 20~27 해산물 예약

