        const tip = new THREE.Vector3(base.x + sx * dx * L, base.y + 0.005 * L, base.z + dz * f.len * L);
        const mid = new THREE.Vector3((base.x + tip.x) / 2, base.y + 0.012 * L, (base.z + tip.z) / 2);
        out.push(fcTaperTube([base.clone(), mid, tip], [0.030 * L, 0.026 * L, 0.019 * L], 5));
        const cap = new THREE.SphereGeometry(0.019 * L, 5, 4);   // 끝을 둥글게 마감(원뿔 끝 금지)
        cap.translate(tip.x, tip.y, tip.z);
