    bk.addColorStop(0, '#4f7a24'); bk.addColorStop(0.24, '#79b03a'); bk.addColorStop(0.5, '#9ed254');
    bk.addColorStop(0.76, '#79b03a'); bk.addColorStop(1, '#4f7a24');
    g.fillStyle = bk; g.fillRect(R.x, R.y, C, C * 0.5);
    const bl = g.createLinearGradient(R.x, 0, R.x + C, 0);   // 배 — 가장자리 초록으로 이어 경계를 아래로
    bl.addColorStop(0.00, '#4f7a24'); bl.addColorStop(0.20, '#83a855'); bl.addColorStop(0.40, '#d7e0a8');
    bl.addColorStop(0.50, '#eeeccc');   // 크림 심지를 좁혀 턱이 하얗게 뜨지 않게
    bl.addColorStop(0.60, '#d7e0a8'); bl.addColorStop(0.80, '#83a855'); bl.addColorStop(1.00, '#4f7a24');
    g.fillStyle = bl; g.fillRect(R.x, R.y + C * 0.5, C, C * 0.5);
