        for (const sp of [-0.30, 0.30]) put(sp, C.R * 2.30, C.R * 0.44, 0);  // 안쪽 노 한 쌍
        for (const sp of [-0.62, 0.62]) put(sp, C.R * 2.05, C.R * 0.40, 0);  // 바깥 노 한 쌍
