        const g = fcBodyGeo(sp, id === 'puffer' || id === 'angler' ? 24 : 20, id === 'puffer' ? 28 : 22);
        shade(g, 'body');
        const uv = g.attributes.uv;
        for (let i = 0; i < uv.count; i++) uv.setXY(i, R.u0 + uv.getX(i) * k, R.v1 - fcV(sp, 1 - uv.getY(i)) * kv);
